          // Set thinkingBudget to 0 to disable "Thinking" and silence the thoughtSignature warning
          thinkingConfig: { thinkingBudget: 0 }
        }
      });

      const responseText = response.text || "Desculpe, tive um problema ao processar sua pergunta. Pode repetir?";
      setAiMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (e: any) {
      console.error("GenAI Error:", e);
      let errorMsg = "O assistente está em manutenção rápida. Que tal falar com nossos vendedores pelo WhatsApp agora mesmo?";

